const $=id=>document.getElementById(id);
const BASE_KEY="gcseBoostV011A",LEGACY=["gcseBoostV0104","gcseBoostV0103","gcseBoostV0102","gcseBoostV0101","gcseBoostV010","gcseBoostV099","gcseBoostV098","gcseBoostV097","gcseBoostV096","gcseBoostV095","gcseBoostV094","gcseBoostV093","gcseBoostV092","gcseBoostV091","gcseBoostV090","gcseBoostV086","gcseBoostV085","gcseBoostV084","gcseBoostV082","gcseBoostV08"];
const schedule=["Maths","English","Science","Geography","German","History","Maths","English","Science","Spanish","Citizenship","Sport Science","Catering","Drama","RE"];
const BOARD={Maths:"Pearson Edexcel",History:"Pearson Edexcel",English:"AQA",Science:"AQA",Geography:"AQA",German:"AQA",Drama:"OCR",Citizenship:"Pearson Edexcel","Sport Science":"OCR",Catering:"WJEC",Spanish:"Pearson Edexcel",RE:"Pearson Edexcel"};
function scienceArea(topic=""){let t=norm(topic);if(/cell|organisation|infection|bioenergetics|homeostasis|inheritance|ecology|biology/.test(t))return "Biology";if(/atomic|periodic|bond|quantitative|chemical|energy change|rate|organic|atmosphere|chemistry/.test(t))return "Chemistry";if(/energy|electric|particle|atomic physics|force|wave|magnet|physics/.test(t))return "Physics";return "Working scientifically"}
function englishAO(topic=""){let t=norm(topic);if(/comparison|compare/.test(t))return "AO3";if(/evaluation|evaluate/.test(t))return "AO4";if(/writing|sentence|craft|description|narrative|viewpoint/.test(t))return "AO5/AO6";if(/language|structure|analysis/.test(t))return "AO2";return "AO1"}
function boardTag(q){if(q.subject==="Science")return `AQA • ${scienceArea(q.topic)}`;if(q.subject==="English")return `AQA • ${englishAO(q.topic)}`;if(q.subject==="Maths")return `Pearson Edexcel • ${state.tiers?.Maths||"Foundation"}`;if(q.subject==="History")return "Pearson Edexcel • Skills";
if(q.subject==="Geography")return "AQA • Geography";
if(q.subject==="German")return `AQA • ${state.tiers?.German||"Foundation"}`;
if(q.subject==="Spanish")return `Pearson Edexcel • ${state.tiers?.Spanish||"Foundation"}`;
if(q.subject==="Drama")return "OCR J316";
if(q.subject==="Citizenship")return "Pearson Edexcel";
if(q.subject==="Sport Science")return "OCR Cambridge National J828";
if(q.subject==="Catering")return "WJEC Level 1/2";
return BOARD[q.subject]||""}

function fresh(){return {xp:0,coins:0,streak:0,lives:3,lastDate:null,history:[],mistakes:[],tiers:{Maths:"Foundation",Science:"Foundation"},readiness:{Maths:null,Science:null},missions:0,bossWins:0,lastBoss:null,totalAnswered:0,totalCorrect:0,dailyCoins:{date:null,missions:0},achievementLevels:{},ownedShop:["avatar_grad"],equipped:{avatar:"avatar_grad",frame:"frame_none",title:"title_none",theme:"theme_default"},dragon:{lastEncounterDate:null,lastRollMission:0,defeated:0,escaped:0,pending:null}}}
function load(){try{for(const k of [KEY,...LEGACY]){const r=localStorage.getItem(k);if(r){const s=Object.assign(fresh(),JSON.parse(r));localStorage.setItem(KEY,JSON.stringify(s));return s}}}catch(e){}return fresh()}

const ACCOUNT_KEY="gcseBoostAccountsV011A";
function loadAccounts(){try{return JSON.parse(localStorage.getItem(ACCOUNT_KEY))||{active:null,learners:{}}}catch(e){return {active:null,learners:{}}}}
function saveAccounts(a){localStorage.setItem(ACCOUNT_KEY,JSON.stringify(a))}
let accounts=loadAccounts();
function makeLearnerId(){return "L-"+Math.random().toString(36).slice(2,6).toUpperCase()+"-"+Date.now().toString(36).slice(-4).toUpperCase()}
function learnerStateKey(id){return BASE_KEY+"::"+id}
let KEY=accounts.active?learnerStateKey(accounts.active):BASE_KEY+"::guest";
function activeLearner(){return accounts.active&&accounts.learners[accounts.active]?accounts.learners[accounts.active]:null}
const TEST_LEARNER_ID="L-ELJP-426T";
function isTestLearner(){return accounts.active===TEST_LEARNER_ID}
function coinBalance(){return isTestLearner()?999999:(Number(state.coins)||0)}
function ensureLearner(name,avatar){let id=makeLearnerId();accounts.learners[id]={id,name:(name||"Learner").trim().slice(0,24)||"Learner",avatar:avatar||"🎓",created:new Date().toISOString()};accounts.active=id;saveAccounts(accounts);KEY=learnerStateKey(id);return accounts.learners[id]}
function accountWelcomeHTML(){return `<div class="account-shell"><div class="account-card"><div class="account-logo">🎓</div><h1>Welcome to GCSE Boost</h1><p>Create a learner profile. Each learner keeps separate revision progress.</p><label>Display name</label><input id="newLearnerName" maxlength="24" placeholder="Display name"><label>Avatar</label><div class="avatar-picks">${["🎓","🚀","⭐","🦊","🐼","🦁"].map((a,i)=>`<button class="avatar-pick ${i?"":"selected"}" data-avatar="${a}" onclick="pickAccountAvatar(this)">${a}</button>`).join("")}</div><input id="newLearnerAvatar" type="hidden" value="🎓"><button class="primary" onclick="createLearnerFromWelcome()">CREATE PROFILE</button><small>V0.11A.28.1 beta · stored on this device only</small></div></div>`}
function pickAccountAvatar(b){document.querySelectorAll(".avatar-pick").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");document.getElementById("newLearnerAvatar").value=b.dataset.avatar}
function createLearnerFromWelcome(){let n=document.getElementById("newLearnerName").value.trim();if(!n){alert("Please enter a display name.");return}ensureLearner(n,document.getElementById("newLearnerAvatar").value);location.reload()}
function showAccountWelcome(){let o=document.createElement("div");o.id="accountWelcome";o.className="account-overlay";o.innerHTML=accountWelcomeHTML();document.body.appendChild(o)}
function switchLearner(id){if(!accounts.learners[id])return;accounts.active=id;saveAccounts(accounts);location.reload()}
function addAnotherLearner(){closeOverlays();showAccountWelcome()}
function accountPanelHTML(){let me=activeLearner(),all=Object.values(accounts.learners);return `<div class="account-page"><button class="back" onclick="goHome()">← Home</button><h1>Beta Accounts</h1><div class="card"><h2>${me?me.avatar+" "+me.name:"Learner"}</h2><p><b>Learner ID:</b> ${me?me.id:"—"}</p><p><b>Storage:</b> This device</p><p><b>Cloud sync:</b> Not connected yet</p><p><b>Version:</b> V0.11A.28</p></div><h2>Profiles on this device</h2><div class="account-list">${all.map(x=>`<button class="account-row ${me&&x.id===me.id?"active":""}" onclick="switchLearner('${x.id}')"><span>${x.avatar}</span><b>${x.name}</b><small>${me&&x.id===me.id?"Current":"Switch"}</small></button>`).join("")}</div><button class="primary" onclick="addAnotherLearner()">+ ADD ANOTHER LEARNER</button><p class="beta-note">V0.11A tests separate learner progress. Cloud accounts come next.</p></div>`}
function showAccounts(){openOverlay("accountOverlay",accountPanelHTML())}

// V0.11B.3.1 — richer algebra: x appears inside the calculation, not only in the instruction.
(function addAlgebraUpgrade(){
 const rows=[];
 const add=(grade,q,answer,why)=>rows.push({subject:"Maths",topic:"Algebra",grade,type:"typed",q,answer:String(answer),why,difficulty:grade,tier:grade<=5?"Foundation":"Higher"});
 for(let x=2;x<=14;x++){
   let a=2+(x%6), b=3+((x*3)%11), total=a*x+b;
   add(4,`Solve ${a}x + ${b} = ${total}. What is x?`,x,`Subtract ${b}, then divide by ${a}.`);
   let c=2+(x%5), d=1+(x%7), rhs=c*(x+d);
   add(5,`Solve ${c}(x + ${d}) = ${rhs}. What is x?`,x,`Divide by ${c}, then subtract ${d}.`);
   let k=1+(x%4), e=4+(x%9), rhs2=(k+1)*x+e;
   add(5,`Solve ${(k+1)}x + ${e} = ${k}x + ${x+e}. What is x?`,x,`Collect the x terms on one side and the constants on the other.`);
   let f=2+(x%4), g=1+(x%6), val=f*x-g;
   add(5,`If x = ${x}, calculate ${f}x − ${g}.`,val,`Substitute ${x} for x, multiply first, then subtract ${g}.`);
 }
 BANK.push(...rows);
})();

