function englishCurriculumPicker(){const cards=Object.entries(ENGLISH_CURRICULUM).map(([section,skills])=>{const n=englishCurriculumCount(section);return `<div class="maths-strand-card"><button class="category-choice" data-cat="${escapeHtml(section)}"><span class="curriculum-card-title"><b>${escapeHtml(section)}</b>${masteryBadge("English",section)}</span><small>${n} current questions</small></button><details><summary>${skills.length} skills · progress by skill</summary><div class="curriculum-skills">${curriculumSkillsHTML("English",section,skills)}</div></details></div>`}).join("");return `<section class="profile-page"><div class="profile-nav"><button class="secondary" onclick="goHome()">← Home</button></div><div class="panel"><h2>English Language</h2><p class="muted">AQA GCSE English Language (8700) · Paper 1 creative reading/writing · Paper 2 viewpoints/perspectives · unseen-text practice.</p><button class="category-choice category-all" data-cat="All">✨ All current skills</button><div class="maths-curriculum-grid">${cards}</div><p class="muted curriculum-note">Extended writing is coached against AO5/AO6. Spoken Language is a separate endorsement and is not included in the GCSE mark.</p></div></section>`}
function categoryFor(q){
 if(q.curriculumArea)return q.curriculumArea;
 if(q.subject==="Maths"&&q.strand)return q.strand;
 if(q.subject==="Science")return q.discipline||scienceArea(q.topic);
 if(q.subject==="English"&&q.section)return q.section;
 let groups=CATEGORY_GROUPS[q.subject]||{},t=(q.topic||"").toLowerCase(),p=(q.prompt||"").toLowerCase();
 for(const [name,keys] of Object.entries(groups))if(keys.some(k=>t.includes(k.toLowerCase())||p.includes(k.toLowerCase())))return name;
 return q.topic||"General";
}
function categoriesFor(subject){
 let cats=[...new Set(pool(subject).map(categoryFor).filter(Boolean))];
 let preferred=Object.keys(CATEGORY_GROUPS[subject]||{});
 return ["All",...preferred.filter(x=>cats.includes(x)),...cats.filter(x=>!preferred.includes(x)).sort()];
}
function categoryPool(subject,category="All"){let p=pool(subject);return category==="All"?p:p.filter(q=>categoryFor(q)===category)}

