// V0.12.7 — rebuilt Pearson Edexcel Probability and Statistics strands.
(function rebuildProbabilityStatisticsV0127(){
 const legacyTopics=new Set(["Probability","Statistics"]);
 for(let i=BANK.length-1;i>=0;i--){const q=BANK[i];if(q.subject==="Maths"&&legacyTopics.has(q.topic))BANK.splice(i,1);}
 const P=[];
 const add=(strand,skill,grade,tier,pattern,q,answer,why,type="typed",opts=null,correct=0)=>{
   const row={subject:"Maths",strand,topic:skill,skill,grade,difficulty:grade,tier,pattern,type,q,why};
   if(type==="mcq"){row.a=opts;row.correct=correct}else row.answer=String(answer);
   P.push(row);
 };
 const pf=[
  ["Probability scale",2,"prob-scale",i=>[`Write ${i%2?"impossible":"certain"} as a probability.`,i%2?0:1,"Probabilities run from 0 (impossible) to 1 (certain)."]],
  ["Single-event probability",3,"single-event",i=>{let r=2+(i%7),b=3+((i*2)%8),t=r+b;return [`A bag has ${r} red and ${b} blue counters. Find P(red) as a fraction.`,`${r}/${t}`,"Probability = favourable outcomes ÷ total outcomes."]}],
  ["Sample spaces",4,"sample-space",i=>{let a=2+(i%4),b=2+((i+1)%4);return [`A spinner has ${a} equally likely outcomes and a coin has ${b===2?2:b} equally likely outcomes. How many outcomes are in the combined sample space?`,a*(b===2?2:b),"Multiply the number of outcomes for independent stages."]}],
  ["Combined events",4,"combined-events",i=>{let n=4+(i%6);return [`A fair ${n}-section spinner is spun twice. Find the probability of getting section 1 both times as a fraction.`,`1/${n*n}`,"For independent events, multiply the probabilities."]}],
  ["Tree diagrams",5,"tree-basic",i=>{let a=2+(i%3),b=a+2;return [`On a tree diagram P(A)=${a}/${b}. Find P(not A) as a fraction.`,`${b-a}/${b}`,"Complementary probabilities sum to 1."]}],
  ["Venn diagrams & set notation",4,"venn-basic",i=>{let both=2+(i%5),onlyA=3+((i*2)%6);return [`In a Venn diagram, ${onlyA} items are in A only and ${both} are in A∩B. How many shown items are in A?`,onlyA+both,"Set A includes A-only and the intersection."]}],
  ["Relative frequency",4,"relative-frequency",i=>{let trials=50+10*(i%6),success=10+5*(i%7); success=Math.min(success,trials-5);return [`An event occurs ${success} times in ${trials} trials. Find its relative frequency as a decimal.`,(success/trials).toFixed(2).replace(/0+$/,'').replace(/\.$/,''),"Relative frequency = successes ÷ trials."]}],
  ["Conditional probability",5,"conditional-intro",i=>{let total=10+(i%6)*2,group=4+(i%5);return [`Of ${total} students who chose sport, ${group} also chose music. Given a student chose sport, find P(music) as a fraction.`,`${group}/${total}`,"Condition on the stated group, so that group becomes the denominator."]}]
 ];
 pf.forEach(([skill,g,pat,make])=>{for(let i=0;i<18;i++){let [q,a,w]=make(i);add("Probability",skill,Math.min(5,g+(i%3===0?1:0)),"Foundation",pat+"-f"+(i+1),q,a,w)}});
 const ph=[
  ["Probability scale",6,"prob-bound",i=>[`A model gives probability ${(1.08+i/100).toFixed(2)}. Is this a valid probability? Answer yes or no.`,"no","A probability cannot be greater than 1."]],
  ["Single-event probability",6,"reverse-prob",i=>{let t=20+5*i,p=2+i;return [`A bag contains ${t} counters. P(green)=${p}/${t}. How many green counters are there?`,p,"Use probability × total outcomes."]}],
  ["Sample spaces",6,"sample-reason",i=>{let n=3+i%4;return [`Two fair ${n}-sided spinners are used. How many ordered outcomes have the same number on both spinners?`,n,"The matching ordered pairs are (1,1), (2,2), and so on."]}],
  ["Combined events",7,"at-least-one",i=>{let n=3+i%5;return [`A fair ${n}-section spinner is spun twice. Find P(at least one 1) as a fraction.`,`${2*n-1}/${n*n}`,"Use 1 − P(no 1), or count the favourable ordered outcomes."]}],
  ["Tree diagrams",7,"tree-without-replacement",i=>{let r=3+i,b=2+i,t=r+b;return [`A bag has ${r} red and ${b} blue counters. Two are taken without replacement. Find P(red then red) as a fraction.`,`${r*(r-1)}/${t*(t-1)}`,"Without replacement, both numerator and denominator change after the first draw."]}],
  ["Venn diagrams & set notation",7,"venn-inclusion",i=>{let A=18+i,B=15+i,both=5+i%4;return [`In a group, n(A)=${A}, n(B)=${B}, n(A∩B)=${both}. Find n(A∪B).`,A+B-both,"Use n(A∪B)=n(A)+n(B)−n(A∩B)."]}],
  ["Relative frequency",6,"expected-frequency",i=>{let rf=(0.25+0.05*i).toFixed(2),n=200+20*i;return [`A relative frequency is ${rf}. Estimate the number of successes in ${n} future trials.`,Math.round(Number(rf)*n),"Expected frequency = relative frequency × number of trials."]}],
  ["Conditional probability",8,"conditional-table",i=>{let group=20+2*i,both=6+i;return [`Among ${group} people with condition B, ${both} also have A. Find P(A|B) as a fraction.`,`${both}/${group}`,"For P(A|B), restrict the denominator to B."]}]
 ];
 ph.forEach(([skill,g,pat,make])=>{for(let i=0;i<7;i++){let [q,a,w]=make(i);add("Probability",skill,g+(i>4?1:0),"Higher",pat+"-h"+(i+1),q,a,w)}});

 const sf=[
  ["Sampling",3,"sampling",i=>[`A school wants opinions from every year group. Which sampling method ensures each year group is represented?`,"stratified","Stratified sampling represents groups in proportion to the population."]],
  ["Tables & charts",3,"charts",i=>{let a=12+i,b=8+(i%7);return [`A frequency table shows ${a} students chose A and ${b} chose B. How many students are represented by these two rows?`,a+b,"Add the frequencies."]}],
  ["Averages & range",3,"mean",i=>{let a=2+i%5,b=4+i%6,c=6+i%7;return [`Find the mean of ${a}, ${b}, ${c}.`,((a+b+c)/3).toFixed(2).replace(/\.00$/,''),"Mean = total ÷ number of values."]}],
  ["Grouped data",5,"group-midpoint",i=>{let lo=10+5*(i%6),hi=lo+10;return [`Find the midpoint of the class interval ${lo} < x ≤ ${hi}.`,(lo+hi)/2,"Class midpoint is halfway between the boundaries."]}],
  ["Scatter graphs",4,"scatter",i=>[`A scatter graph rises from left to right. What type of correlation does this suggest?`,"positive","As one variable increases, the other tends to increase."]],
  ["Time series",4,"time-series",i=>{let q1=20+i,q2=q1+5+(i%4);return [`A time series rises from ${q1} to ${q2}. What is the increase?`,q2-q1,"Subtract the earlier value from the later value."]}],
  ["Histograms",5,"frequency-density",i=>{let f=20+2*i,w=4+(i%4);return [`A histogram class has frequency ${f} and class width ${w}. Find the frequency density.`,(f/w).toFixed(2).replace(/\.00$/,''),"Frequency density = frequency ÷ class width."]}],
  ["Cumulative frequency",5,"cumfreq",i=>{let a=10+i,b=12+i,c=8+i;return [`The first three class frequencies are ${a}, ${b}, ${c}. Find the cumulative frequency after the third class.`,a+b+c,"Cumulative frequency is a running total."]}],
  ["Box plots",5,"iqr",i=>{let q1=10+i,q3=q1+12+(i%5);return [`A box plot has Q1=${q1} and Q3=${q3}. Find the interquartile range.`,q3-q1,"IQR = Q3 − Q1."]}],
  ["Comparing distributions",5,"compare-spread",i=>[`Dataset A has IQR ${8+i%5}; dataset B has IQR ${14+i%5}. Which dataset is more consistent?`,"A","A smaller IQR means less spread and greater consistency."]]
 ];
 sf.forEach(([skill,g,pat,make])=>{for(let i=0;i<18;i++){let [q,a,w]=make(i);add("Statistics",skill,Math.min(5,g+(i%4===0?1:0)),"Foundation",pat+"-f"+(i+1),q,a,w)}});
 const sh=[
  ["Sampling",6,"sampling-bias",i=>[`A survey about school lunches is conducted only among students who bring packed lunches. What problem does this create?`,"bias","The sampling frame systematically excludes relevant groups."]],
  ["Tables & charts",6,"chart-reason",i=>{let f=30+i*2,t=120+i*5;return [`In a pie chart, ${f} of ${t} responses are category A. Find the sector angle to the nearest degree.`,Math.round(360*f/t),"Sector angle = frequency ÷ total × 360°."]}],
  ["Averages & range",6,"reverse-mean",i=>{let n=5+i,total=60+10*i,newmean=(total+20+i)/ (n+1);return [`${n} values have total ${total}. One more value, ${20+i}, is added. Find the new mean to 2 d.p.`,newmean.toFixed(2),"Add the new value to the total and divide by the new number of values."]}],
  ["Grouped data",7,"estimated-mean",i=>{let m1=5,m2=15,f1=4+i,f2=6+i;return [`Grouped data has midpoint ${m1} with frequency ${f1}, and midpoint ${m2} with frequency ${f2}. Estimate the mean to 2 d.p.`,((m1*f1+m2*f2)/(f1+f2)).toFixed(2),"Use Σ(midpoint × frequency) ÷ Σfrequency."]}],
  ["Scatter graphs",6,"line-best-fit",i=>{let x=4+i,y=2*x+3;return [`A line of best fit is y=2x+3. Estimate y when x=${x}.`,y,"Substitute x into the line of best fit."]}],
  ["Time series",6,"moving-average",i=>{let a=10+i,b=13+i,c=16+i;return [`Find the 3-point moving average of ${a}, ${b}, ${c}.`,((a+b+c)/3).toFixed(2).replace(/\.00$/,''),"Add the three values and divide by 3."]}],
  ["Histograms",7,"hist-reverse",i=>{let d=3+i,w=5+i%3;return [`A histogram bar has frequency density ${d} and class width ${w}. Find the frequency.`,d*w,"Frequency = frequency density × class width."]}],
  ["Cumulative frequency",7,"cf-percentile",i=>{let n=80+10*i;return [`A cumulative-frequency graph represents ${n} values. At what cumulative frequency is the upper quartile read?`,0.75*n,"The upper quartile is at 75% of the data."]}],
  ["Box plots",7,"box-outlier",i=>{let q1=10+i,q3=20+i,iqr=10;return [`For Q1=${q1}, Q3=${q3}, use the 1.5×IQR rule to find the upper outlier boundary.`,q3+15,"Upper boundary = Q3 + 1.5×IQR."]}],
  ["Comparing distributions",7,"compare-centre-spread",i=>[`Class A has median ${60+i} and IQR 12. Class B has median ${57+i} and IQR 18. Which class has the higher typical score and is more consistent?`,"A","A has both the higher median and the smaller IQR."]]
 ];
 sh.forEach(([skill,g,pat,make])=>{for(let i=0;i<6;i++){let [q,a,w]=make(i);add("Statistics",skill,g+(i>3?1:0),"Higher",pat+"-h"+(i+1),q,a,w)}});
 BANK.push(...P);
})();

// V0.12.8 — Maths quality audit repair: strengthen Higher Number and remove true duplicate items.
(function mathsQualityRepairV0128(){
 const add=(skill,grade,pattern,q,answer,why)=>BANK.push({subject:"Maths",strand:"Number",topic:skill,skill,grade,difficulty:grade,tier:"Higher",pattern,type:"typed",q,answer:String(answer),why});
 const nums=[2,3,4,5,6,7,8,9,10,12,15,20];
 nums.forEach((b,i)=>{ const n=2+(i%3); add("Powers, roots & indices",6+(i%2),"negative-index-h"+(i+1),`Write ${b}^-${n} as 1/n. What is n?`,Math.pow(b,n),"A negative index means take the reciprocal: a^-n = 1/a^n."); });
 const rec=[["0.333...",3],["0.666...",3],["0.111...",9],["0.222...",9],["0.444...",9],["0.555...",9],["0.777...",9],["0.888...",9],["0.090909...",11],["0.181818...",11],["0.272727...",11],["0.363636...",11]];
 rec.forEach(([d,den],i)=>add("Fractions",6+(i>7?1:0),"recurring-decimal-h"+(i+1),`The recurring decimal ${d} can be written as a fraction with denominator ${den}. What is the numerator in its simplest form?`, i<8 ? [1,2,1,2,4,5,7,8][i] : [1,2,3,4][i-8],"Convert the recurring decimal to a fraction, then simplify."));
 const sf=[[3,4,2,3],[6,5,3,2],[8,3,4,2],[9,6,3,4],[2,7,5,3],[4,8,2,5],[5,9,3,6],[7,4,2,7],[3,6,4,5],[8,5,2,6],[6,7,3,5],[9,4,2,8]];
 sf.forEach(([a,e,b,f],i)=>{let val=(a*b),pow=e+f; while(val>=10){val/=10;pow++} add("Standard form",6+(i%3===0),"sf-multiply-h"+(i+1),`(${a} × 10^${e}) × (${b} × 10^${f}) = k × 10^${pow}. Find k.`,val,"Multiply the numbers, add the powers of ten, then normalise the coefficient.")});
 const surd=[[18,2,3],[32,2,4],[50,2,5],[72,2,6],[98,2,7],[108,3,6],[147,3,7],[192,3,8],[200,2,10],[242,2,11],[288,2,12],[363,3,11]];
 surd.forEach(([n,r,k],i)=>add("Exact calculation & surds",6+(i>5?1:0),"simplify-surd-h"+(i+1),`√${n} = k√${r}. Find k.`,k,"Take the largest square factor out of the square root."));
 const bounds=[[12.4,.1],[8.7,.1],[3.25,.01],[19.6,.1],[42.35,.01],[6.125,.001],[81.4,.1],[0.76,.01],[15.55,.01],[2.375,.001],[104.5,1],[250,10]];
 bounds.forEach(([x,u],i)=>add("Bounds & estimation",6+(i>7?1:0),"upper-bound-h"+(i+1),`${x} is rounded to the nearest ${u}. Give the upper bound.`,x+u/2,"The upper bound is half a rounding unit above the stated value."));
 const pf=[[72,2],[108,3],[200,2],[432,3],[675,3],[980,2],[1215,3],[1372,2],[1575,3],[2025,3],[2401,7],[3125,5]];
 pf.forEach(([n,pv],i)=>{let m=n,c=0;while(m%pv===0){c++;m/=pv}add("Factors, multiples & primes",6+(i>7?1:0),"prime-power-h"+(i+1),`In the prime factorisation of ${n}, what is the power of ${pv}?`,c,"Repeatedly divide by the prime to find its exponent in the prime factorisation.")});
 // Remove only exact duplicate assessment items (same prompt and same options for MCQ).
 const seen=new Set();
 for(let i=BANK.length-1;i>=0;i--){const q=BANK[i]; if(q.subject!=="Maths")continue; const key=(q.q||"").trim().toLowerCase()+"|"+JSON.stringify(q.a||[]).toLowerCase(); if(seen.has(key))BANK.splice(i,1); else seen.add(key);}
})();

