// V0.20.0 — map the remaining V1 banks into current qualification curriculum areas,
// remove exact duplicate assessment records, and strengthen the previously small RE bank.
(function v0200RemainingSubjects(){
 const remaining=new Set(["History","Geography","German","Spanish","Drama","Citizenship","Sport Science","Catering","RE"]);
 const area=(q)=>{const t=((q.topic||"")+" "+(q.q||"")).toLowerCase(),s=q.subject;
  if(s==="Geography"){if(/hazard|ecosystem|coast|river|physical/.test(t))return "Living with the physical environment";if(/urban|economic|resource|human/.test(t))return "Challenges in the human environment";if(/fieldwork|issue evaluation/.test(t))return "Geographical applications";return "Geographical skills"}
  if(s==="German"){if(/people|lifestyle|identity|family|health|school|future/.test(t))return "People and lifestyle";if(/popular|culture|music|film|free time|festival/.test(t))return "Popular culture";if(/communication|world|travel|environment|media|technology/.test(t))return "Communication and the world around us";return "Language skills"}
  if(s==="Spanish"){if(/identity|family|friend|relationship|personal/.test(t))return "My personal world";if(/health|food|sport|lifestyle/.test(t))return "Lifestyle and wellbeing";if(/local|town|shopping|transport|neighbour/.test(t))return "My neighbourhood";if(/media|technology|gaming|film|music/.test(t))return "Media and technology";if(/school|future|work|study/.test(t))return "Studying and my future";if(/travel|tour|holiday|accommodation/.test(t))return "Travel and tourism";return "Language skills"}
  if(s==="Drama"){if(/devis/.test(t))return "Devising drama";if(/performance skill|vocal|physical|character|presenting/.test(t))return "Presenting and performing texts";return "Performance and response"}
  if(s==="Citizenship"){if(/identity|communit|right|responsib|living/.test(t))return "Living together in the UK";if(/democra|government|parliament|election/.test(t))return "Democracy at work in the UK";if(/law|justice|crime|court/.test(t))return "Law and justice";if(/media|power|influence|pressure|international/.test(t))return "Power and influence";return "Taking citizenship action"}
  if(s==="Sport Science"){if(/injury|medical|warm/.test(t))return "R180 Injury risk and medical conditions";if(/training|fitness/.test(t))return "R181 Principles of training";if(/body|technology|response/.test(t))return "R182 Body response and technology";return "R183 Nutrition and sports performance"}
  if(s==="Catering"){if(/industry|hospitality|customer|safety|haccp/.test(t))return "Unit 1: Hospitality and catering industry";return "Unit 2: Hospitality and catering in action"}
  if(s==="History"){if(/crime|punishment|medicine|warfare|migrant/.test(t))return "Thematic study";if(/anglo|norman|richard|john|henry|elizabeth/.test(t))return "British depth study";if(/spain|new world|british america|american west|cold war|middle east/.test(t))return "Period study";if(/russia|soviet|weimar|nazi|mao|china|usa|vietnam|civil rights/.test(t))return "Modern depth study";return "Historical enquiry skills"}
  if(s==="RE"){if(/christ|catholic|islam|muslim|juda|jew|buddh|hindu|sikh/.test(t))return "Religion and belief";if(/peace|conflict|crime|punishment|human right|religious life/.test(t))return "Religion, peace and conflict";if(/explain|compare|evaluate|analyse/.test(t))return "Evaluation skills";return "Philosophy and ethics"}
  return q.topic||"General";
 };
 for(const q of BANK)if(remaining.has(q.subject))q.curriculumArea=area(q);
 // RE: add compact, original recall/application items so every V1 area has meaningful depth.
 const reFacts=[
  ["Religion and belief","Christianity","Trinity","Which Christian belief describes God as Father, Son and Holy Spirit?","The Trinity"],
  ["Religion and belief","Christianity","Incarnation","What term describes the Christian belief that God became human in Jesus?","Incarnation"],
  ["Religion and belief","Islam","Tawhid","What is the Islamic belief in the oneness of God called?","Tawhid"],
  ["Religion and belief","Islam","Five Pillars","Which pillar requires Muslims to fast during Ramadan?","Sawm"],
  ["Religion and belief","Judaism","Covenant","What term describes a binding agreement between God and his people in Judaism?","Covenant"],
  ["Religion and belief","Buddhism","Four Noble Truths","Which teaching explains suffering and the path beyond it?","Four Noble Truths"],
  ["Religion and belief","Hinduism","Karma","What term describes the moral consequences of actions?","Karma"],
  ["Religion and belief","Sikhism","sewa","What Sikh term means selfless service?","sewa"],
  ["Philosophy and ethics","Relationships and families","marriage","Give one reason religious believers may value marriage.","commitment"],
  ["Philosophy and ethics","Life and death","sanctity of life","What principle says human life has special value because it is sacred?","sanctity of life"],
  ["Philosophy and ethics","Good and evil","free will","What term means the ability to make genuine moral choices?","free will"],
  ["Philosophy and ethics","Beliefs about God","omnipotent","What word means all-powerful when describing God?","omnipotent"],
  ["Religion, peace and conflict","Peace and conflict","pacifism","What is the belief that violence and war should be rejected called?","pacifism"],
  ["Religion, peace and conflict","Crime and punishment","retribution","Which aim of punishment focuses on offenders receiving a deserved penalty?","retribution"],
  ["Religion, peace and conflict","Crime and punishment","rehabilitation","Which aim of punishment tries to reform an offender?","rehabilitation"],
  ["Religion, peace and conflict","Human rights","human dignity","What idea supports treating every person as having inherent worth?","human dignity"]
 ];
 for(let r=0;r<6;r++)for(const [a,topic,skill,stem,ans] of reFacts){BANK.push({subject:"RE",curriculumArea:a,topic,skill,grade:Math.min(8,3+r),type:"typed_text",q:`${stem} ${r?`Apply this in revision scenario ${r+1}.`:''}`.trim(),keywords:[ans],why:`A strong response should identify ${ans} and explain it accurately.`,pattern:`re-${skill}-${r}`,difficulty:Math.min(8,3+r)})}
 // exact duplicate assessment cleanup for remaining subjects only.
 const seen=new Set(),keep=[];for(const q of BANK){if(!remaining.has(q.subject)){keep.push(q);continue}const sig=(q.subject+"|"+(q.q||"").trim().toLowerCase()+"|"+JSON.stringify(q.a||[]));if(seen.has(sig))continue;seen.add(sig);keep.push(q)}BANK.length=0;BANK.push(...keep);
})();

